        /// <summary>
        /// How far a frame's aspect ratio may drift from the solved canvas's before the entry is
        /// treated as describing a <i>different crop</i>.
        ///
        /// <para>Two percent, because the exporter rounds the solved canvas to whole pixels: a
        /// 255.333 px symbol exports as 435 px at zoom 1.704, and 255.3/255.3 against 435/435 is
        /// exactly 1.0 while 130/125 against 80/77 is 1.040 against 1.039. A crop that actually
        /// changed — <c>visualScythe</c>, 48x61 against 58x61 — lands at 21.7 % and is refused.</para>
        /// </summary>
        public const float AspectTolerance = 0.02f;

        /// <summary>
        /// The anchor for <paramref name="visual"/>, in <b>pixels of the frame being drawn</b>, or
        /// false when the name is unknown or the frame is a different crop than the solved canvas.
        /// </summary>
        /// <param name="frameWidth">The sprite's width in pixels.</param>
        /// <param name="frameHeight">The sprite's height in pixels.</param>
        public static bool TryGet(string visual, float frameWidth, float frameHeight,
                                  out UnityEngine.Vector2 anchor)
        {
            anchor = UnityEngine.Vector2.zero;
            if (string.IsNullOrEmpty(visual) || !ByVisual.TryGetValue(visual, out Entry entry))
            {
                return false;
            }

            if (frameWidth <= 0f || frameHeight <= 0f || entry.Width <= 0f || entry.Height <= 0f)
            {
                return false;
            }

            // A size mismatch on its own is benign — the exporter's zoom differs per pass, and
            // `visualNecrBoss` ships at 435 px against a 255.3 px child. What is not benign is a
            // different aspect: that is another crop, and the anchor solved for one crop does not
            // describe it.
            float entryAspect = entry.Width / entry.Height;
            float frameAspect = frameWidth / frameHeight;
            if (Math.Abs(frameAspect - entryAspect) > AspectTolerance * entryAspect)
            {
                return false;
            }

            // Rescale into the frame's own pixels. Each axis uses its own ratio so a canvas the
            // exporter rounded by a pixel does not bias the other axis.
            float sx = frameWidth / entry.Width;
            float sy = frameHeight / entry.Height;
            anchor = new UnityEngine.Vector2(entry.X * sx, entry.FeetGap * sy);
            return true;
        }

        /// <summary>
        /// The gap between the sprite's bottom edge and the unit's origin, for a frame of the given
        /// size — or false when the visual is unknown or the entry was solved against another size.
        ///
        /// <para>The caller multiplies this by the visual's own scale, because <c>localScale</c>
        /// scales the sprite about the transform origin and the gap is measured in source pixels.</para>
        /// </summary>
        public static bool TryGetFeetGap(string visual, float frameWidth, float frameHeight,
                                         out float feetGap)
        {
            if (!TryGet(visual, frameWidth, frameHeight, out UnityEngine.Vector2 anchor))
            {
                feetGap = 0f;
                return false;
            }

            feetGap = anchor.y;
            return true;
        }
